from datetime import date, timedelta
import re, csv
from collections import defaultdict

ref = date(2025,8,12)
ranges = {
    'today': (ref, ref),
    'last_7_days': (ref - timedelta(days=6), ref),
    'last_30_days': (ref - timedelta(days=29), ref),
    'month_to_date': (date(ref.year, ref.month, 1), ref),
    'total': (date(1,1,1), date(9999,12,31)),
}
sev = ['ERROR','WARNING','INFO']
counts = {p:{s:0 for s in sev} for p in ranges}
for path in sorted(Path('/app/logs').glob('*.log')):
    m = re.match(r'^(\d{4})-(\d{2})-(\d{2})_.+\.log$', path.name)
    if not m:
        continue
    d = date(*map(int, m.groups()))
    line_counts = {s:0 for s in sev}
    for line in path.read_text(encoding='utf-8', errors='replace').splitlines():
        for s in sev:
            if f'[{s}]' in line:
                line_counts[s] += 1
    for p,(a,b) in ranges.items():
        if a <= d <= b:
            for s in sev:
                counts[p][s] += line_counts[s]

csv_rows = []
with open('/app/summary.csv', newline='', encoding='utf-8') as f:
    r = csv.reader(f)
    header = next(r)
    for row in r:
        csv_rows.append(row)

print('HEADER', header)
print('CSV_ROWS', len(csv_rows))
order = ['today','last_7_days','last_30_days','month_to_date','total']
for p in order:
    for s in sev:
        expected = counts[p][s]
        actual = None
        for row in csv_rows:
            if row[0]==p and row[1]==s:
                actual = int(row[2]); break
        print(p, s, expected, actual, 'MATCH' if expected==actual else 'MISMATCH')
